package com.bananalab.lite;
import java.io.*;import java.net.*;import java.util.*;import java.util.regex.*;import org.json.*;
/** Bounded HTTPS-only public web reader; sources cannot execute tools or update model weights. */
final class ResearchWeb{
 static final int MAX_BYTES=262144;static final long BUDGET=22000;interface Transport{String get(String url,long deadline)throws Exception;}
 static final Transport NETWORK=(url,deadline)->fetch(url,deadline);
 static final class Doc{String title,url,text;long saved;Doc(String t,String u,String x){title=t;url=u;text=x.substring(0,Math.min(6000,x.length()));saved=System.currentTimeMillis();}JSONObject json()throws Exception{return new JSONObject().put("title",title).put("url",url).put("text",text).put("saved",saved);}static Doc read(JSONObject j){Doc d=new Doc(j.optString("title"),j.optString("url"),j.optString("text"));d.saved=j.optLong("saved");return d;}}
 static final class Batch{List<Doc> docs=new ArrayList<>();String warning="";}
 static boolean safeHost(String host){if(host==null)return false;host=host.toLowerCase(Locale.ROOT);return !host.equals("localhost")&&!host.endsWith(".localhost")&&!host.endsWith(".local")&&!host.endsWith(".internal")&&!host.matches("[0-9.]+")&&!host.contains(":")&&host.contains(".");}
 static URI publicUri(String address)throws Exception{URI u=new URI(address);if(!"https".equalsIgnoreCase(u.getScheme())||!safeHost(u.getHost())||u.getUserInfo()!=null||u.getPort()!=-1&&u.getPort()!=443)throw new IOException("Solo páginas HTTPS públicas sin credenciales.");return u;}
 static boolean publicAddress(InetAddress a){byte[] b=a.getAddress();if(a.isAnyLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress()||a.isMulticastAddress())return false;if(b.length==16&&((b[0]&0xfe)==0xfc))return false;return !(b.length==4&&((b[0]&255)==0||(b[0]&255)==100&&(b[1]&255)>=64&&(b[1]&255)<=127||(b[0]&255)==169&&(b[1]&255)==254));}
 static String fetch(String address,long deadline)throws Exception{for(int hops=0;hops<4;hops++){check(deadline);URI uri=publicUri(address);for(InetAddress a:InetAddress.getAllByName(uri.getHost()))if(!publicAddress(a))throw new IOException("Destino de red privado rechazado.");HttpURLConnection c=(HttpURLConnection)uri.toURL().openConnection();c.setInstanceFollowRedirects(false);int timeout=(int)Math.max(1,Math.min(6500,deadline-System.currentTimeMillis()));c.setConnectTimeout(timeout);c.setReadTimeout(timeout);c.setRequestProperty("User-Agent","BananaResearch/0.38 (personal Android research; bounded requests)");c.setRequestProperty("Accept","text/html,application/json,text/plain");try{int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");if(location==null)throw new IOException("Redirección incompleta.");address=uri.resolve(location).toString();continue;}if(status!=200)throw new IOException("HTTP "+status);String type=c.getContentType();if(type!=null&&!type.toLowerCase(Locale.ROOT).matches(".*(text/|json).*"))throw new IOException("La fuente no es texto.");if(c.getContentLength()>MAX_BYTES)throw new IOException("La página supera el límite de lectura.");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){check(deadline);if(out.size()+n>MAX_BYTES)throw new IOException("La página supera el límite de lectura.");out.write(buf,0,n);}}String charset="UTF-8";if(type!=null){Matcher m=Pattern.compile("charset=([A-Za-z0-9_-]+)",Pattern.CASE_INSENSITIVE).matcher(type);if(m.find())charset=m.group(1);}return out.toString(charset);}finally{c.disconnect();}}throw new IOException("Demasiadas redirecciones.");}
 static void check(long deadline)throws IOException{if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Consulta cancelada.");if(System.currentTimeMillis()>deadline)throw new IOException("Se agotó el tiempo de consulta.");}
 static String article(String html){Matcher m=Pattern.compile("(?is)<(main|article)\\b[^>]*>(.*?)</\\1\\s*>").matcher(html);String best="";while(m.find())if(m.group(2).length()>best.length())best=m.group(2);String content=best.isEmpty()?html:best;Matcher paragraphs=Pattern.compile("(?is)<p\\b[^>]*>(.*?)</p\\s*>").matcher(content);StringBuilder text=new StringBuilder();while(paragraphs.find()){String paragraph=clean(paragraphs.group(1));if(paragraph.length()>=50)text.append(paragraph).append(paragraph.matches("(?s).*[.!?]$")?" ":". ");}return text.length()>=80?text.toString():clean(content);}
 static String clean(String html){String s=html.replaceAll("(?is)<(head|script|style|nav|footer|header|form|noscript|svg)\\b[^>]*>.*?</\\1\\s*>"," ").replaceAll("(?s)<[^>]+>"," ");s=s.replace("&nbsp;"," ").replace("&amp;","&").replace("&quot;","\"").replace("&#39;","'").replace("&lt;","<").replace("&gt;",">");Matcher m=Pattern.compile("&#(x[0-9a-fA-F]+|[0-9]+);").matcher(s);StringBuffer b=new StringBuffer();while(m.find()){String v=m.group(1),value=" ";try{int cp=Integer.parseInt(v.startsWith("x")?v.substring(1):v,v.startsWith("x")?16:10);if(Character.isValidCodePoint(cp))value=new String(Character.toChars(cp));}catch(Exception ignored){}m.appendReplacement(b,Matcher.quoteReplacement(value));}m.appendTail(b);return b.toString().replaceAll("\\s+"," ").trim();}
 static List<Doc> parseSearch(String html)throws Exception{List<Doc> out=new ArrayList<>();Matcher m=Pattern.compile("(?is)<a\\b([^>]*class=[\"'][^\"']*result__a[^\"']*[\"'][^>]*)>(.*?)</a>").matcher(html);Set<String> used=new HashSet<>();while(m.find()&&out.size()<4){Matcher href=Pattern.compile("href=[\"']([^\"']+)[\"']",Pattern.CASE_INSENSITIVE).matcher(m.group(1));if(!href.find())continue;String link=href.group(1).replace("&amp;","&");if(link.startsWith("//"))link="https:"+link;URI u=new URI(link);if(u.getHost()!=null&&(u.getHost().equals("duckduckgo.com")||u.getHost().endsWith(".duckduckgo.com"))&&u.getRawQuery()!=null){for(String pair:u.getRawQuery().split("&"))if(pair.startsWith("uddg="))link=URLDecoder.decode(pair.substring(5),"UTF-8");}try{publicUri(link);}catch(Exception ignored){continue;}if(used.add(link))out.add(new Doc(clean(m.group(2)),link,""));}return out;}
 static Batch search(String query,Transport transport)throws Exception{long deadline=System.currentTimeMillis()+BUDGET,generalDeadline=deadline-6500;Batch batch=new Batch();List<Doc> hits=new ArrayList<>();try{hits=parseSearch(transport.get("https://html.duckduckgo.com/html/?q="+URLEncoder.encode(query,"UTF-8"),generalDeadline));if(hits.isEmpty())batch.warning="El buscador general no devolvió resultados legibles; puede estar bloqueado o haber cambiado.";}catch(Exception e){if(Thread.currentThread().isInterrupted())throw e;batch.warning="No pude consultar el buscador general.";}for(Doc hit:hits){if(batch.docs.size()==3||System.currentTimeMillis()>generalDeadline-1000)break;try{String html=transport.get(hit.url,generalDeadline);String body=article(html);if(body.length()<80||ResearchAnswer.score(query,hit.title+" "+body)==0)continue;hit.text=body.substring(0,Math.min(6000,body.length()));batch.docs.add(hit);}catch(Exception e){if(Thread.currentThread().isInterrupted())throw e;}}if(batch.docs.isEmpty()&&System.currentTimeMillis()<deadline-500){try{String address="https://es.wikipedia.org/w/api.php?action=query&generator=search&gsrnamespace=0&gsrlimit=3&gsrsearch="+URLEncoder.encode(query,"UTF-8")+"&prop=extracts&exintro=1&explaintext=1&exchars=3000&format=json";JSONObject data=new JSONObject(transport.get(address,deadline));JSONObject q=data.optJSONObject("query"),pages=q==null?null:q.optJSONObject("pages");if(pages!=null){Iterator<String> keys=pages.keys();while(keys.hasNext()){JSONObject p=pages.getJSONObject(keys.next());if(!p.optString("extract").isEmpty())batch.docs.add(new Doc(p.optString("title"),"https://es.wikipedia.org/?curid="+p.getLong("pageid"),p.optString("extract")));}}if(!batch.docs.isEmpty())batch.warning="Cobertura limitada a Wikipedia en español; no es una búsqueda completa de la web ni de noticias.";}catch(Exception e){if(Thread.currentThread().isInterrupted())throw e;}}Collections.sort(batch.docs,(a,b)->Double.compare(3*ResearchAnswer.score(query,b.title)+ResearchAnswer.score(query,b.text),3*ResearchAnswer.score(query,a.title)+ResearchAnswer.score(query,a.text)));return batch;}
 static Batch read(String address,Transport transport)throws Exception{publicUri(address);long deadline=System.currentTimeMillis()+BUDGET;String html=transport.get(address,deadline);Matcher t=Pattern.compile("(?is)<title[^>]*>(.*?)</title>").matcher(html);String title=t.find()?clean(t.group(1)):new URI(address).getHost();Batch b=new Batch();String body=article(html);if(body.length()>40)b.docs.add(new Doc(title,address,body));return b;}
}
